import json
p='output/solution.json'; d=json.load(open(p)); assert set(d)=={'sequence'}
allowed={'none','Measurement Error','Missing Step','Order Error','Other','Preparation Error','Technique Error','Temperature Error','Timing Error'}
lengths={'A':946.5,'B':694.4,'C':779.9,'D':783.2,'E':1044.3,'F':652.1,'G':809.7,'H':608.4,'I':1149.6,'J':837.4,'K':770.4,'L':676.5,'M':1020.7,'N':603.0,'O':687.5,'P':928.9,'Q':748.8,'R':709.2,'S':649.8,'T':816.2,'U':914.6,'V':766.0}
seen={v:[] for v in lengths}
for i,e in enumerate(d['sequence']):
 assert set(e)=={'video','id','t_start','t_end','error'},(i,e)
 assert e['video'] in lengths and isinstance(e['id'],int) and 1<=e['id']<=84 and e['error'] in allowed
 assert 0<=e['t_start']<e['t_end']<=lengths[e['video']],e
 seen[e['video']].append(e)
for v,a in seen.items():
 assert a,v
 for i in range(len(a)-1):
  assert (a[i]['t_start'],a[i]['id']) <= (a[i+1]['t_start'],a[i+1]['id']),(v,a[i],a[i+1])
print(f'valid: {len(d[\"sequence\"])} entries across {len(seen)} videos')
PY"

